<?php
namespace App\Modules\Counselor\Services;
use App\Modules\Counselor\Models\Counselor;use App\Modules\Counselor\Repositories\CounselorRepositoryInterface;use Illuminate\Support\Facades\{DB,Storage};use Illuminate\Contracts\Pagination\LengthAwarePaginator;
class CounselorService {public function __construct(private CounselorRepositoryInterface $repo){}public function index(array $f=[]):LengthAwarePaginator{return $this->repo->paginate($f);}public function find(int $id):?Counselor{return $this->repo->find($id);}public function create(array $data):Counselor{$specialties=$data['specialty_ids']??[];unset($data['specialty_ids']);$upload=$data['avatar']??null;unset($data['avatar']);if($upload)$data['avatar']=$upload->store('counselors','public');try{return DB::transaction(function()use($data,$specialties){$c=$this->repo->create($data);$c->specialties()->sync($specialties);return $c->load('specialties');});}catch(\Throwable $e){if($upload)Storage::disk('public')->delete($data['avatar']);throw $e;}}public function update(Counselor $c,array $data):Counselor{$hasSpecialties=array_key_exists('specialty_ids',$data);$specialties=$data['specialty_ids']??[];unset($data['specialty_ids']);$upload=$data['avatar']??null;unset($data['avatar']);$old=$c->avatar;if($upload)$data['avatar']=$upload->store('counselors','public');try{$result=DB::transaction(function()use($c,$data,$hasSpecialties,$specialties){$c=$this->repo->update($c,$data);if($hasSpecialties)$c->specialties()->sync($specialties);return $c->load('specialties');});}catch(\Throwable $e){if($upload)Storage::disk('public')->delete($data['avatar']);throw $e;}if($upload && $old)Storage::disk('public')->delete($old);return $result;}public function delete(Counselor $c):void{$this->repo->delete($c);}}
